userscript.function:

//추가될 행의 아이디를 정의
var maxRowId = new Date().getTime() + '' + dhx4.newId();
if (mode == 'copy') {
    var selectedRow = gridObj.getGridChangedRows("SELECTED");
    if (selectedRow.length < 1) {
        Alert(Sepoa.cache.text.get('MESSAGE.9999'));
    }
    for (var i = 0; i < selectedRow.length; i++) {
        gridObj.addRow(maxRowId, '', 0);
        gridObj.copyRowContent(selectedRow[i], maxRowId);
        gridObj.cells(maxRowId, gridObj.getColIndexById('SELECTED')).setValue("1");
        gridObj.cells(maxRowId, gridObj.getColIndexById('SAVED')).setValue("");
        gridObj.cells(maxRowId++, gridObj.getColIndexById('NOT_NULL')).setValue("0");
    }
} else {
    var firstRowData = {};
    if (gridObj.getRowsNum() > 1) {
        var rid = gridObj.getRowId(0);
        firstRowData.GRID_ID = gridObj.cells(rid, gridObj.getColIndexById('GRID_ID')).getValue();
    }
    gridObj.addRow(maxRowId, '', 0);
    gridObj.cells(maxRowId, gridObj.getColIndexById('SELECTED')).setValue("1");
    gridObj.cells(maxRowId, gridObj.getColIndexById('NOT_NULL')).setValue("0");
    gridObj.cells(maxRowId, gridObj.getColIndexById('GRID_ID')).setValue(firstRowData.GRID_ID || "");
    gridObj.cells(maxRowId, gridObj.getColIndexById('COL_MAX_LEN')).setValue("10000");
    gridObj.cells(maxRowId, gridObj.getColIndexById('COL_VISIBLE')).setValue("true");
    gridObj.cells(maxRowId, gridObj.getColIndexById('COL_COLOR')).setValue("Rcolor");
}
gridObj.showRow(gridObj.getRowId(0));


var selectedRow = gridObj.getGridChangedRows("SELECTED");
for (var i = selectedRow.length - 1; i >= 0; i--) {
    if (gridObj.cells(selectedRow[i], gridObj.getColIndexById('SAVED')).getValue() != "Y") {
        gridObj.deleteRow(selectedRow[i]);
    }
}
if (gridObj.getGridChangedRows("SELECTED").length > 0 && Confirm(Sepoa.cache.text.get('MESSAGE.1015'), function(result) {
        if (result) {
            gridObj.editStop();
            gridObj.postTransaction(window.CONTEXT_NAME + '/SepoaGrid.sux', ['mode=doSave', 'PROCESS_ID=sepoa.svc.admin.AD_022_3', 'METHOD=doDelete'], 'SELECTED');
        }
    }));
if (gridObj.getRowsNum() > 0) {
    gridObj.showRow(gridObj.getRowsNum());
}


if (arg) {
    dataOutput.setValue('GRID_ID', arg);
}
dataOutput.addFilter(filterObj);
gridObj.postConnection(window.CONTEXT_NAME + '/SepoaGrid.sux', ['mode=doQuery', 'PROCESS_ID=sepoa.svc.admin.AD_022_3']);
gridObj.clearAll(false);
if (!gridObj._fake) {
    gridObj.splitAt(6);
    gridObj.setSizes();
}


var msg = obj.getUserData("", "message");
var status = obj.getUserData("", "status");

if (status == "true") {
    callFunction('p', 'showPreview', [Sepoa.cache.grid.get(dataOutput.getValue('GRID_ID'))]);
}


var mode = obj.mode;
var status = obj.status;
var message = obj.message;
if (status == 'true') {
    Alert(message);
    doQuery();
    callFunction('p', 'doList', [true]);
} else {
    Alert(message);
}


var m = gridObj.getRowsNum();
var nextSeq = 1;
for (var i = 0; i < m; i++) {
    var rid = gridObj.getRowId(i);
    if (gridObj.cells(rid, gridObj.getColIndexById('COL_VISIBLE')).getValue() != 'true') {
        seq = 9999
    } else if ((gridObj.cells(rid, gridObj.getColIndexById('COL_WIDTH_' + Sepoa.info.LANGUAGE)).getValue() || 0) <= 0) {
        seq = 9999
    } else {
        seq = nextSeq;
        nextSeq++;
    }
    gridObj.cells(gridObj.getRowId(i), gridObj.getColIndexById('COL_SEQ')).setValue(seq * 10);
}

gridObj.sortRows(gridObj.getColIndexById('COL_SEQ'));
gridObj.allRowsChecked('SELECTED', true);


var header = gridObj.getColumnId(cInd);
if (stage == 0) {
    return true;
} else if (stage == 1) {
    return true;
} else if (stage == 2) {
    var gId = gridObj.cells(rId, gridObj.getColIndexById('GRID_ID')).getValue();
    if (gId != '') {
        dataOutput.setValue('GRID_ID', gId);
    }

    if ((header.indexOf('COL_WIDTH') == 0) && (nValue.replace(/[0-9*.]/gi, "").length > 0)) {
        return false;
    }

    var colNames = ['CODE', 'CONTENTS_KO', 'COL_TYPE', 'COL_SEQ', 'COL_ALIGN', 'COL_FORMAT', 'COL_WIDTH_KO', 'COL_VISIBLE'];
    var objData = [];
    var data = {};

    var rowCount = this.getRowsNum();
    var rowIDs = [];

    for (var i = 0; i < rowCount; i++) {
        rowIDs.push(parseInt(this.getRowId(i)));
    }

    for (var i = 0; i < rowIDs.length; i++) {
        var rin = rowIDs[i];
        var rowDataObject = this.getRowDataObject(rin);

        colNames.forEach(function(element) {
            data[element] = rowDataObject[element];
        });
        objData.push(data);
        data = {};
    }

    objData.sort(function(a, b) {
        if (a.COL_SEQ > b.COL_SEQ) {
            return 1;
        }

        if (a.COL_SEQ < b.COL_SEQ) {
            return -1;
        }

        return 0;
    });

    callFunction('AD_022_5', 'realTimePreview', [objData]);
    return true;
}
return false;


        	var header = gridObj.getColumnId(cIn);

        	if(header == 'MODULE') {
        		var moduleSelectCallback = function(target, value, customParam) {
					target.setValue(value);

					var selectedIdx = gridObj.getColIndexById('SELECTED');
					var rowID = customParam.rowID;
					gridObj.cells(rowID, selectedIdx).setChecked(true);
				}
				var targetCell = gridObj.cells(rID, cIn);
				var customParam = {rowID: rID};

				PopupOpenPost(window.CONTEXT_NAME + '/Admin/ModuleConfiguration/AdminModuleConfigurationSelectPopup.sux', {target: targetCell, selectedValue: targetCell.getValue(), customParam: customParam}, moduleSelectCallback, 800, null, Sepoa.cache.text.get('AD_022_3.MODULE_SELECT'), 'SELECT_MODULE');
        	}


gridObj.clearAll(false);
for (var i in gridDataList) {
    var maxRowId = gridObj.getRowsNum() + 1;
    gridObj.addRow(maxRowId, '', gridObj.getRowsNum());
    gridObj.cells(maxRowId, gridObj.getColIndexById("SELECTED")).setValue(1);
    for (var j in Object.keys(gridDataList[i])) {
        var key = Object.keys(gridDataList[i])[j];
        var value = gridDataList[i][key];
        gridObj.cells(maxRowId, gridObj.getColIndexById(key)).setValue(value);
    }
}


var url = '/servlets/sepoa.svl.excel.SepoaGridExcel?mode=up';
var formData = new FormData();
formData.append('gridExcelUploadInput', file);

if (forceFlag) {
    url += "&force=true";
}

$.ajax({
    url: url,
    method: 'post',
    data: formData,
    async: false,
    cache: false,
    contentType: false,
    processData: false,
    dataType: "json",
    success: function(res) {
        if (res.status == 1) {
            renderGridFromExcelData(res.result);
        } else if (res.status == 2) {
            Confirm(Sepoa.cache.text.get("MESSAGE.EXCEL_UPLOAD_SAME_GRID_ERROR"), function(flag) {
                if (flag) {
                    sendExcelData(file, true)
                }
            })
        } else {
            Alert(Sepoa.cache.text.get("MESSAGE.EXCEL_UPLOAD_PARSING_FAIL_ERROR"));
        }

    }
});


doServiceAjax('sepoa.svc.common.COMMON', 'CONNECTION', 'getActiveLanguage', void 0, function(so) {
    if (so.status != 1) {
        Alert(so.message);
        return;
    }
    var gridOptions = Sepoa.cache.grid.load(window.CONTEXT_NAME + '/resource/ux/admin/grid/AD_022_3.js');
    var result = {};
    var secondHeader = [];

    for (var key in gridOptions) {
        if (key == 'SAVED') continue;

        gridOptions[key].COL_VISIBLE = 'true';
    }

    gridOptions['APPLY_ALL'].COL_WIDTH = '50';
    gridOptions['CODE'].COL_WIDTH = '100';
    gridOptions['MODULE'].COL_WIDTH = '100';
    gridOptions['COL_ALIGN'].COL_WIDTH = '80';
    gridOptions['COL_COLOR'].COL_WIDTH = '80';
    gridOptions['COL_COMBO'].COL_WIDTH = '100';
    gridOptions['COL_FORMAT'].COL_WIDTH = '100';
    gridOptions['COL_MAX_LEN'].COL_WIDTH = '100';
    gridOptions['COL_SEQ'].COL_WIDTH = '80';
    gridOptions['COL_SORT'].COL_WIDTH = '80';
    gridOptions['COL_TYPE'].COL_WIDTH = '120';
    gridOptions['COL_VISIBLE'].COL_WIDTH = '100';
    gridOptions['COL_WIDTH'].COL_WIDTH = '60';
    gridOptions['CONTENTS'].COL_WIDTH = '180';
    gridOptions['GRID_ID'].COL_WIDTH = '80';
    gridOptions['NOT_NULL'].COL_WIDTH = '60';
    gridOptions['SELECTED'].COL_WIDTH = '40';
    gridOptions['SELECTED_YN'].COL_WIDTH = '100';
    gridOptions['TEMPLATE'].COL_WIDTH = '100';

    var sf = new SepoaFormater(so.result[0]);
    //result.SPLIT_DEBUG = {
    //    LANGUAGE: "KO",
    //    SELECTED_YN: "",
    //    COL_FORMAT: "",
    //    COL_SEQ: "0",
    //    TEXT_STYLE: "",
    //    NOT_NULL: "0",
    //    COL_WIDTH: "0",
    //    COL_MAX_LEN: "10000",
    //    CONTENTS: "",
    //    COL_SORT: "",
    //    MODULE: "",
    //    COL_VISIBLE: "true",
    //    CODE: "SPLIT_DEBUG",
    //    COL_TYPE: "edtxt",
    //    COL_ALIGN: "center",
    //    COL_COLOR: "Rcolor",
    //    TEMPLATE: "",
    //    COL_COMBO: ""
    //}
    //secondHeader.push("");
    for (var key in gridOptions) {
        if (["CONTENTS", "COL_WIDTH"].indexOf(key) + 1) {
            for (var i = 0; i < sf.getRowCount(); i++) {
                var item = $.extend({}, gridOptions[key]);
                var language = sf.getValue("LANGUAGE", i)
                if (i != 0) {
                    if(key == "CONTENTS" && i == 1){
                        item.CONTENTS = gridOptions[key].CONTENTS;
                    }else{
                        item.CONTENTS = "#cspan";
                    }
                    item.NOT_NULL = "0";
                }
                item.CODE = item.CODE + "_" + language
                result[key + "_" + language] = item;
                secondHeader.push(sf.getValue("TEXT1", i));
                item = null;
            }
        } else {
            result[key] = gridOptions[key];
            secondHeader.push("#rspan");
        }
    }
    console.log(result)
    gridObj = $sObject.gridObj = new SepoaDhtmlXGridObject(gridbox, 'gridObj', result);
    gridObj._onDnDFlag = true;
    gridObj.setGridDraw();
    gridObj.attachHeader(secondHeader);
    gridObj.setSizes();
    gridObj.setDataOutput(dataOutput)
    gridObj.attachEvent('onTXE', doSaveEnd_grid);
    gridObj.attachEvent('onXLE', doQueryEnd);
    gridObj.attachEvent('onEditCell', onEditCell);
    gridObj.attachEvent('onRowSelect', onRowSelect);
    gridObj.attachEvent('onDrop', onDrop);
    Sepoa.attachEvent('onLoad', function() {
        gridObj.setSizes();
    });
    SUX.attachEvent('onWindowResize', function() {
        gridbox.style.width = '';
        gridbox.style.height = '100%';
        gridObj.setSizes();
    });
    gridObj.ednNullEnabled(true);
}, false);


var isFileInput = document.getElementById('gridExcelUploadInput');
if (isFileInput != null) {
    document.body.removeChild(isFileInput);
}

//File Input Box 생성
var fileInput = document.createElement('input');
fileInput.setAttribute('id', 'gridExcelUploadInput');
fileInput.setAttribute('type', 'file');
fileInput.setAttribute('name', 'gridExcelUploadInput');
fileInput.style.display = 'none';

fileInput.onchange = function() {
    var fileExt = this.value.split('.').pop().toLowerCase();
    var file = fileInput.files[0];

    if ($.inArray(fileExt, ['xlsx', 'xls']) == -1) {
        Alert(Sepoa.cache.text.get("MESSAGE.EXCEL_UPLOAD_EXT_FAIL_ERROR"));
        return;
    }

    sendExcelData(file);
};

fileInput.click();
